INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scuttle Up', 'Scuttle Up is a punishing platformer where you play as a depressed-yet-agile crab. Your journey begins in a boring corporate office, and your mission is to escape the 9-5 and ascend to the top of a mysterious island. A prize worthy of a king crab awaits you at the top, but do you have the resolve to make it?' FROM games WHERE igdb_id = 292811 ON CONFLICT (game_id, language_code) DO NOTHING;
