INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Landmine Princess', 'Landmine Princess is the sophomoric release for Jeistar that is a spin on the dating simulator genre. It takes the "fast-love" rogue template and interpolates it with the explosive personality of Mina, a "Landmine" girl whose personality is explored deeply. Stats passive aggressively update based on your decisions with important random questions Mina throws at you.' FROM games WHERE igdb_id = 342881 ON CONFLICT (game_id, language_code) DO NOTHING;
