INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twin Colliders', 'In this small arcade game, the player controls two catchers simultaneously—one on the right and one on the left. In the game, particles always move toward each other, and they must be caught at the point of collision using either the right or left catcher. If an annihilation is missed and it explodes, the player will lose one heart. Losing three hearts results in a game over.' FROM games WHERE igdb_id = 339058 ON CONFLICT (game_id, language_code) DO NOTHING;
