INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpscare to Live', 'The game features the player taking the role of a ghost who tasks themselves with alerting the person who lives in the home they haunt with making them aware of a person outside who appears threatening. The ghost can''t communicate well with the person living in their home, however, so they wind up making a mess of things and have to scare the person around the home to safety away from the threat outside at the windows.' FROM games WHERE igdb_id = 374715 ON CONFLICT (game_id, language_code) DO NOTHING;
