INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon-Slaying War God', 'This officially licensed Legend of Mir game features the classic Iron Triangle class system, three classes with free transfers, and hero team-ups, offering a brand-new combat experience! BOSSes lurk everywhere, with legendary gear exploding everywhere; Shabak sieges and exciting PKs! This game perfectly recreates the classic Legend of Mir gameplay.' FROM games WHERE igdb_id = 367746 ON CONFLICT (game_id, language_code) DO NOTHING;
