INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('plant-nursery-simulator', 332575, '2025-06-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9fmv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3dyg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plant Nursery Simulator', 'Plant Nursery Simulator is a cozy management simulation game where you run your own plant shop. Stock shelves with a variety of plants, order supplies, hire and manage staff, and expand your nursery to attract more customers. Grow and nurture plants to keep your store thriving while balancing costs and profits. With stylized visuals and a relaxing atmosphere, the game offers a wholesome experience for players who enjoy strategic planning and creative shop management.' FROM games WHERE igdb_id = 332575 ON CONFLICT (game_id, language_code) DO NOTHING;
