INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BND Legenden: Operation Blackout', 'BND-Legenden: Operation Blackbox ist das erste offizielle Videogame des BND. Das Spiel vermischt Action-Adventure und Stealth mit weiteren beliebten Gaming-Elementen. In einem futuristischen Setting erhält Agentin AJ den Auftrag, geheime Informationen zu einer gefährlichen Cyberwaffe zu beschaffen.' FROM games WHERE igdb_id = 388772 ON CONFLICT (game_id, language_code) DO NOTHING;
