INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Legacy: Ultimate Drive', 'In Speed Legacy, players find themselves in a futuristic metropolis fueled by speed and adrenaline. As a former professional racer stripped of your license, your mission is to reclaim your reputation and expose the corrupt automotive giant Phoenix Motors. Participate in intense drag races, drift challenges, police chases, and high-risk deliveries. With a mix of dynamic storytelling and thrilling gameplay, every mission brings you closer to becoming a racing legend.' FROM games WHERE igdb_id = 378186 ON CONFLICT (game_id, language_code) DO NOTHING;
