INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MapHunt', 'MapHunt is an educational geography game centered on world exploration through 360-degree street-level panoramas. Players are placed in various global locations and must use visual environmental clues to identify their surroundings and locate specific hidden objects. The game utilizes an AI-powered verification system to confirm discoveries, combining geographical learning with observational puzzles. Players develop spatial awareness and global knowledge by navigating through real-world environments to complete search objectives within a set timeframe.' FROM games WHERE igdb_id = 386905 ON CONFLICT (game_id, language_code) DO NOTHING;
