INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firescape', 'Firescape is a short game where you play as a firefighter. Need to put out a fire? Use your fire extinguisher! Need to get to the fire if it''s too high? Fly your fire extinguisher! But be careful, something hides in the fog. He is watching. He always watches. He knows, you are somewhere here. Try to stay inside or he will see you.' FROM games WHERE igdb_id = 342731 ON CONFLICT (game_id, language_code) DO NOTHING;
