INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Wears The Crown?', 'Test your brain and your brawn in the toughest chess game ever made! Play against a tough chess engine to build your path and climb upward to claim the crown, but be careful! One small blunder and you risk losing your progress. Heavy is the head that wears the crown, but who will wear it?' FROM games WHERE igdb_id = 297985 ON CONFLICT (game_id, language_code) DO NOTHING;
