INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gun-dealer-simulator', 355790, '2025-07-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa5su.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3vmi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
