INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bioleech', 'Bioleech is a satirical FPS that blends fast-paced action with recycling and resource-management mechanics. Beneath the appearance of a “planetary rehabilitation mission,” players uncover an oppressive corporate system exploiting both the environment and its workers. A “serious anti-game” that uses dark humor and social critique to make you reflect while fighting for survival.' FROM games WHERE igdb_id = 366419 ON CONFLICT (game_id, language_code) DO NOTHING;
