INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sokowand', 'Sokowand is a top-down puzzle game which fuses sokoban-inspired puzzles with a magical floor that can be ripped out. Need to cross a gap? Use the floor next to you! Push boxes to open doors, manipulate signals, redirect laser by rotating mirrors and rewire entire floors full of electricity.' FROM games WHERE igdb_id = 335261 ON CONFLICT (game_id, language_code) DO NOTHING;
