INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shake the Baby!', 'Shake the Baby! is a fast-paced satirical boomer shooter with a very peculiar weapon system. Pick up a wide variety of babies and merge them into an even more powerful baby. Rip apart your foes in arena combat or traverse carefully made tactical levels. Just remember: SHAKE. THE. BABY!' FROM games WHERE igdb_id = 337068 ON CONFLICT (game_id, language_code) DO NOTHING;
