INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Retro Game Trivia', 'RetroTrivia.Games is a free daily video game trivia site focused on classic and retro games from the 70s, 80s, 90s, and early 2000s. Players test their knowledge through multiple game modes like Clue, Screenshot, Box Art, and Letter Reveal. Each mode challenges players to guess the game title based on visual or text clues, with new trivia posted daily. Track your streaks, earn badges, and explore retro gaming history with fun facts and blog posts alongside the trivia.
