INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Back 3: Spooky', 'After escaping the Art Horror Dimension from the last game, the protagonist awakens in an enigmatic faction, only to find his escape companion Gao Yan missing. When interrogated about Gao Yan''s whereabouts, Ye Tan – who survived the Haunted Manor Dimension – appears as a member of the faction and rescues you. With her assistance, you enter a wholly distinct new dimension unlike the previous two, embarking on another adventure. In this uncharted dimension, you''ll forge new alliances, confront fresh dangers, and your choices will determine the branching paths to multiple endings.' FROM games WHERE igdb_id = 359535 ON CONFLICT (game_id, language_code) DO NOTHING;
