INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fly-light', 361497, '2025-08-18', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar41o5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fly Light', 'Fly Light is a game in which you need to turn on lamps located on 4 different sides, thereby attracting midges to you. Thus, you need to lure as many midges as possible to the exploding area. But you need to be careful, because if you attract a midge too close to you, it can sit on the lamp, thereby partially blocking the glow range of the lamp, which will mean that you will not be able to attract a new midge so easily. You will lose when the midges stick to one of the lamps so that it can no longer shine. You get points for the number of midges destroyed using explosions.' FROM games WHERE igdb_id = 361497 ON CONFLICT (game_id, language_code) DO NOTHING;
