INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batty Zabella 2 XOXO XMAS', 'Batty''s back for a Christmas-themed adventure! Don''t expect a typical holiday season, though - there are still plenty of creepy, crawly things lurking in her home. Batty Zabella 2 XOXO XMAS is a spooky-fun point-and-click adventure game for the Game Boy. This time, she’s back with even more sass, new puzzles, and a haunted mansion full of creepy surprises.' FROM games WHERE igdb_id = 347084 ON CONFLICT (game_id, language_code) DO NOTHING;
