INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom World', 'Save the kingdom from the monsters! Kingdom World is a fast, side-scrolling action game where every run counts. Dodge obstacles, defeat enemies, and scoop up coins to grow stronger. Visit the Market to buy and equip weapons—from swords to a fireball-flinging staff—and get some bling from the epic chest! Don''t forget to upgrade your stats, there''s some strong monsters! Fill out your bestiary to see who has been terrorizing the kingdom so you know who to target next!' FROM games WHERE igdb_id = 373945 ON CONFLICT (game_id, language_code) DO NOTHING;
