INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Creative Framework', 'Digital Creative Framework (DCF) is a multiplayer sandbox where players terraform voxel worlds, build structures, and share custom verses via Steam Workshop. Set in customizable garages and expansive landscapes, it blends vehicle physics, character switching, and drone flight for collaborative world-building. Core mechanics include VerseGate for real-time world control—weather, time, spawns—and runtime asset imports for models, textures, and sounds.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 379655 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
