INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donuts for Deer Teeth', 'Steal donuts to feed your fat cryptid wife or die trying! Donuts for Deer Teeth is a top-down, roguelite brawler where your only goal is to steal whatever you can get your grubby little raccoon paws on before shoving it in the face of some weird deer-faced skull thing.' FROM games WHERE igdb_id = 343027 ON CONFLICT (game_id, language_code) DO NOTHING;
