INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eidolons Cross', '"Eidolons Cross" is a PvP strategy card game that combines poker and heroes. The game merges poker hand comparison mechanics with hero formations that trigger skills, creating entirely new strategies and gameplay. Players will recruit various heroes, build unique decks, and face off against opponents in poker battles to determine the victor.' FROM games WHERE igdb_id = 376617 ON CONFLICT (game_id, language_code) DO NOTHING;
