INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just the Boss Fights', 'A classic 2D platformer RPG with a twist: the game skips all the story, dialogue, exploration, and grind, leaving only the bosses themselves! Unfortunately, our hero wasn''t quite prepared for this shift into a boss rush, and finds himself confused at every turn.' FROM games WHERE igdb_id = 337366 ON CONFLICT (game_id, language_code) DO NOTHING;
