INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slavic Winter Simulator', 'Slavic Winter Simulator is an authentic experience that recreates the celebration of New Year among residents of the post-Soviet space in the 2000s, offering nostalgic emotions. Throw snowballs at your in-game friends, enjoy the magical atmosphere of New Year from the 2000s, and relive the carefree days of childhood.' FROM games WHERE igdb_id = 326345 ON CONFLICT (game_id, language_code) DO NOTHING;
